sp_widget.client_script:
function($scope, $rootScope, $timeout) {
    var chartInstance = null;

    $scope.anoSelecionado = "";
    $scope.exibirGrafico = false;

    function carregarDadosDoServer() {
    var filtros = {
        ano: $scope.anoSelecionado || ""
    };

    $scope.server.get(filtros).then(function(response) {
        var listaDados = response.data.dadosGrafico || [];

        $timeout(function() {
            inicializarGrafico(listaDados);
        }, 500); 
    });
}


    $rootScope.$on('filtroAnoIndicadoresSelecionado', function(event, ano) {
        $scope.anoSelecionado = ano;
        carregarDadosDoServer();
    });

    carregarDadosDoServer();

    function inicializarGrafico(listaDados) {
    if (!listaDados || listaDados.length === 0) {
        if (chartInstance) {
            chartInstance.destroy();
            chartInstance = null;
        }
        $scope.exibirGrafico = false;
        $scope.$applyAsync();
        return;
    }

    $scope.exibirGrafico = true;
    $scope.$applyAsync();

    var labels = [];
    var camData = [];
    var cdiData = [];
    var dolarSofrData = [];
    var selicData = [];
    var tjlpData = [];
    var trData = [];  // NOVO array para TR

    for (var i = 0; i < listaDados.length; i++) {
        labels.push(listaDados[i].ano);
        camData.push(listaDados[i].cam);
        cdiData.push(listaDados[i].cdi);
        dolarSofrData.push(listaDados[i].dolar_sofr);
        selicData.push(listaDados[i].selic);
        tjlpData.push(listaDados[i].tjlp);
        trData.push(listaDados[i].tr); // adiciona os dados de TR
    }

    var contexto = document.getElementById('graficoIndicadores').getContext('2d');

    if (chartInstance) {
        chartInstance.destroy();
    }

    chartInstance = new Chart(contexto, {
        type: 'bar',
        data: {
            labels: labels,
            datasets: [
                { 
                    label: 'CAM (Coeficiente de Atualização Monetária (IPCA + 4% a.ae a variação acumulada taxa Selic)',
                    data: camData,
                    backgroundColor: '#4A75B1',
                    borderColor: '#4A75B1',
                    borderWidth: 1,
                    yAxisID: 'y'
                },
                {
                    label: 'CDI (Certificado deposito bancário)',
                    data: cdiData,
                    backgroundColor: '#6BB7F0',
                    borderColor: '#6BB7F0',
                    borderWidth: 1,
                    yAxisID: 'y'
                },
                {
                    label: 'Dólar SOFR (Dólar americano taxa de juros americano)',
                    data: dolarSofrData,
                    backgroundColor: '#293273',
                    borderColor: '#293273',
                    borderWidth: 1,
                    yAxisID: 'y'
                },
                {
                    label: 'TJLP (Taxa de Juros de Longo Prazo)',
                    data: tjlpData,
                    backgroundColor: '#04B4CB',
                    borderColor: '#04B4CB',
                    borderWidth: 1,
                    yAxisID: 'y'
                },
               /* {
                    label: 'SELIC (Taxa básica de juros da economia)',
                    data: selicData,
                    type: 'line', // Linha para destacar
                    borderColor: '#E66734',
                    backgroundColor: '#E66734',
                    borderWidth: 3,
                    tension: 0.4,
                    fill: false,
                    yAxisID: 'y2',
                    pointBackgroundColor: '#E66734',
                    pointBorderColor: '#E66734',
                    pointRadius: 3
                },
                {
                    label: 'TR (Taxa Referencial)',
                    data: trData,
                    type: 'line',  // Linha igual SELIC
                    borderColor: '#137A8F',
                    backgroundColor: '#137A8F',
                    borderWidth: 3,
                    tension: 0.4,
                    fill: false,
                    yAxisID: 'y2', 
                    pointBackgroundColor: '#137A8F',
                    pointBorderColor: '#137A8F',
                    pointRadius: 3
                }*/
            ]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                x: {
                    title: {
                        display: true,
                        text: 'Ano'
                    }
                },
                y: {
                    beginAtZero: true,
                    title: {
                        display: true,
                        text: 'Indicadores (%)'
                    }
                },
                y2: {
                    beginAtZero: true,
                    position: 'right',
                    title: {
                        display: true,
                        text: 'SELIC / TR (%)'
                    },
                    grid: {
                        drawOnChartArea: false
                    }
                }
            },
            plugins: {
                legend: {
                    position: 'top'
                },
                tooltip: {
                    callbacks: {
                        label: function(context) {
                            return context.dataset.label + ': ' + context.parsed.y + ' %';
                        }
                    }
                }
            }
        }
    });
}

}

sp_widget.css:
canvas {
  display: block;
  margin: 0 auto;
}

h3, div, span {
 font-family: 'Roboto Flex', sans-serif;
}

/* --- Media Queries para Responsividade --- */

/* Telas Pequenas (Mobile S, M, L - até 767px) */
@media (max-width: 767px) {
  canvas {
    max-width: 90%; /* Ajustar a largura máxima do canvas */
  }
  h3 {
    font-size: 1rem; /* Ajustar o tamanho da fonte do título */
  }
}

/* Tablets (iPad Mini, iPad Air, Surface Duo, Galaxy Z Fold 5 - 768px até 1023px) */
@media (min-width: 768px) and (max-width: 1023px) {
  canvas {
    max-width: 80%;
  }
  h3 {
    font-size: 1.1rem;
  }
}

/* Laptops e Telas Maiores (iPad Pro, Surface Pro 7, Laptops, 4K - 1024px em diante) */
@media (min-width: 1024px) {
  canvas {
    max-width: none;
  }
  h3 {
  }
}

/* Ajustes para o Surface Duo (540x720) */
@media (width: 540px) and (height: 720px) {
    canvas {
        max-width: 95%;
    }
}

/* Ajustes para Galaxy Z Fold 5 (max-width: 350px) */
@media (max-width: 350px) {
    h3 {
        font-size: 0.9rem;
    }
}

sp_widget.script:
(function() {
    input = input || {};
    var anoFiltro = input.ano || "";

    var gr = new GlideRecord('x_sded9_portal_t_0_u_indicadores_economicos');
    if (anoFiltro !== "") {
        gr.addQuery('u_ano', anoFiltro);
    }

    gr.orderBy('u_ano');
    gr.query();

    var listaDados = [];

    while (gr.next()) {
        listaDados.push({
            ano: gr.getValue('u_ano'),
            cam: parseFloat(gr.getValue('u_cam')) || 0,
            cdi: parseFloat(gr.getValue('u_cdi')) || 0,
            dolar_sofr: parseFloat(gr.getValue('u_dolar_sofr')) || 0,
           // selic: parseFloat(gr.getValue('u_selic')) || 0,
            tjlp: parseFloat(gr.getValue('u_tjlp')) || 0,
					 //	tr: parseFloat(gr.getValue('u_tr')) || 0
        });
    }
	//gs.addInfoMessage(JSON.stringify(listaDados))

    data.dadosGrafico = listaDados;
})();
